use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let limit = 200000
    let mut sieve: Vec<bool> = []
    let mut counts: Vec<int> = []
    let mut largest: Vec<int> = []
    let mut i = 0
    while i <= limit {
        sieve.push(true)
        counts.push(0)
        largest.push(0)
        i += 1
    }
    let mut p = 2
    while p * p <= limit {
        if sieve[p] {
            let mut m = p * p
            while m <= limit {
                sieve[m] = false
                m += p
            }
        }
        p += 1
    }
    let mut c = 0
    let mut last = 0
    let mut k = 2
    while k <= limit {
        if sieve[k] {
            c += 1
            last = k
        }
        counts[k] = c
        largest[k] = last
        k += 1
    }
    let mut first = true
    let mut t = 0
    for line in text.lines() {
        let s = line.trim()
        if s.len() == 0 { continue }
        if first {
            first = false
            let tt: int = s.parse().unwrap_or(0)
            t = tt
            continue
        }
        let n: int = s.parse().unwrap_or(0)
        if n < 2 {
            println("0 none")
        } else {
            println("${counts[n]} ${largest[n]}")
        }
    }
}

